package com.mealmate.delivery; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/deliveries") class DeliveryController{final DeliveryRepository r;DeliveryController(DeliveryRepository x){r=x;}@GetMapping("/{id}")Delivery get(@PathVariable UUID id){return r.findById(id).orElseThrow();}@PostMapping("/{id}/status")Delivery status(@PathVariable UUID id,@RequestBody Status s){var d=r.findById(id).orElseThrow();d.setStatus(s.status());return r.save(d);}record Status(String status){}}
